content:
/* Reset & Base Styles */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-surface-hover: #f1f5f9;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;
  --color-text-main: #1e293b;
  --color-text-sub: #64748b;
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-text: #ffffff;
  --color-danger: #ef4444;
  --color-danger-hover: #dc2626;
  --color-danger-text: #ffffff;
  --color-active-tool: #eff6ff;
  --color-active-border: #3b82f6;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  user-select: none;
  -webkit-user-select: none;
}

/* App Container */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* App Header */
.app-header {
  text-align: center;
  padding: 8px 16px;
}

.app-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  letter-spacing: -0.02em;
}

.app-guide {
  font-size: 0.875rem;
  color: var(--color-text-sub);
  margin-top: 4px;
}

/* Main Layout (Flex for desktop, column for mobile) */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex: 1;
}

@media (min-width: 860px) {
  .main-layout {
    flex-direction: row;
    align-items: flex-start;
  }
}

/* Toolbar Container */
.toolbar-container {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 16px;
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
  gap: 20px;
  width: 100%;
}

@media (min-width: 860px) {
  .toolbar-container {
    width: 290px;
    flex-shrink: 0;
    position: sticky;
    top: 16px;
  }
}

/* Tool Sections */
.tool-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-title {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-sub);
}

/* Color Palette */
.color-palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  align-items: center;
}

.color-swatch {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-full);
  border: 2px solid #ffffff;
  box-shadow: 0 0 0 1px var(--color-border), var(--shadow-sm);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  position: relative;
  outline: none;
  padding: 0;
}

.color-swatch:hover {
  transform: scale(1.1);
}

.color-swatch:active {
  transform: scale(0.95);
}

.color-swatch.active {
  transform: scale(1.15);
  box-shadow: 0 0 0 2px #ffffff, 0 0 0 4px var(--color-active-border), var(--shadow-md);
}

/* Custom Color Picker Button & Hidden Input */
.custom-color-btn {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-full);
  border: 2px dashed var(--color-border-hover);
  background: conic-gradient(red, yellow, lime, aqua, blue, magenta, red);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.15s ease, border-color 0.15s ease;
  padding: 0;
}

.custom-color-btn:hover {
  transform: scale(1.1);
}

.custom-color-btn:active {
  transform: scale(0.95);
}

.custom-color-input {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

/* Size Controls */
.size-control-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.size-slider {
  flex: 1;
  accent-color: var(--color-primary);
  height: 6px;
  border-radius: 3px;
  background-color: var(--color-border);
  cursor: pointer;
}

.size-preview-dot {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-bg);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  flex-shrink: 0;
}

.size-value {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text-sub);
  min-width: 36px;
  text-align: right;
}

/* Action & Tool Buttons */
.action-btn-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tool-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 14px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background-color: var(--color-surface);
  color: var(--color-text-main);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease;
  min-height: 42px;
  outline: none;
}

.tool-btn:hover:not(:disabled) {
  background-color: var(--color-surface-hover);
  border-color: var(--color-border-hover);
}

.tool-btn:active:not(:disabled) {
  transform: translateY(1px);
}

.tool-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.tool-btn.active {
  background-color: var(--color-active-tool);
  border-color: var(--color-active-border);
  color: var(--color-primary);
  box-shadow: inset 0 0 0 1px var(--color-active-border);
}

.tool-btn-primary {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-primary-text);
  box-shadow: var(--shadow-sm);
}

.tool-btn-primary:hover:not(:disabled) {
  background-color: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
  color: var(--color-primary-text);
}

.tool-btn-danger {
  color: var(--color-danger);
  border-color: #fecaca;
  background-color: #fef2f2;
}

.tool-btn-danger:hover:not(:disabled) {
  background-color: #fee2e2;
  border-color: #fca5a5;
  color: var(--color-danger-hover);
}

/* Canvas Area */
.canvas-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
  min-height: 440px;
  height: 64vh;
}

.drawing-canvas {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  background-color: #ffffff;
  cursor: crosshair;
}

/* Mobile Adjustments (<= 480px) */
@media (max-width: 480px) {
  .app-container {
    padding: 10px;
    gap: 12px;
  }

  .app-title {
    font-size: 1.25rem;
  }

  .toolbar-container {
    padding: 12px;
    gap: 14px;
  }

  .canvas-area {
    min-height: 380px;
    height: 52vh;
  }

  .color-palette {
    grid-template-columns: repeat(5, 1fr);
    gap: 8px;
  }

  .color-swatch,
  .custom-color-btn {
    width: 34px;
    height: 34px;
  }

  .tool-btn {
    font-size: 0.8125rem;
    padding: 8px 10px;
  }
}

export type ToolType = 'pen' | 'eraser';

export interface DrawingSettings {
  color: string;
  size: number;
  tool: ToolType;
}

export interface ToolbarProps {
  settings: DrawingSettings;
  onSettingsChange: (newSettings: Partial<DrawingSettings>) => void;
  onClear: () => void;
  onUndo: () => void;
  onDownload: () => void;
  canUndo: boolean;
}

export interface CanvasBoardProps {
  settings: DrawingSettings;
  onHistoryChange: (canUndo: boolean) => void;
  clearTrigger: number;
  undoTrigger: number;
  downloadTrigger: number;
}

import { ChangeEvent } from 'react';
import { Pencil, Eraser, Undo2, Trash2, Download } from 'lucide-react';
import { ToolbarProps } from '../types';

const PRESET_COLORS = [
  { name: '黒', value: '#1e293b' },
  { name: '赤', value: '#ef4444' },
  { name: '青', value: '#3b82f6' },
  { name: '緑', value: '#10b981' },
  { name: '黄', value: '#eab308' },
  { name: '橙', value: '#f97316' },
  { name: '紫', value: '#8b5cf6' },
  { name: 'ピンク', value: '#ec4899' },
];

export default function Toolbar({
  settings,
  onSettingsChange,
  onClear,
  onUndo,
  onDownload,
  canUndo,
}: ToolbarProps) {
  const handleColorSelect = (color: string) => {
    onSettingsChange({ color, tool: 'pen' });
  };

  const handleCustomColorChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSettingsChange({ color: e.target.value, tool: 'pen' });
  };

  const handleSizeChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSettingsChange({ size: Number(e.target.value) });
  };

  const isPresetSelected = PRESET_COLORS.some((c) => c.value === settings.color);

  return (
    <aside className="toolbar-container" aria-label="描画ツールバー">
      {/* ツール選択（ペン / 消しゴム） */}
      <section className="tool-section">
        <h2 className="section-title">ツール</h2>
        <div className="action-btn-group">
          <button
            type="button"
            className={`tool-btn ${settings.tool === 'pen' ? 'active' : ''}`}
            onClick={() => onSettingsChange({ tool: 'pen' })}
            aria-pressed={settings.tool === 'pen'}
          >
            <Pencil size={18} />
            <span>ペン</span>
          </button>
          <button
            type="button"
            className={`tool-btn ${settings.tool === 'eraser' ? 'active' : ''}`}
            onClick={() => onSettingsChange({ tool: 'eraser' })}
            aria-pressed={settings.tool === 'eraser'}
          >
            <Eraser size={18} />
            <span>消しゴム</span>
          </button>
        </div>
      </section>

      {/* カラーパレット */}
      <section className="tool-section">
        <h2 className="section-title">ペンの色</h2>
        <div className="color-palette">
          {PRESET_COLORS.map((preset) => {
            const isActive = settings.tool === 'pen' && settings.color === preset.value;
            return (
              <button
                key={preset.value}
                type="button"
                className={`color-swatch ${isActive ? 'active' : ''}`}
                style={{ backgroundColor: preset.value }}
                onClick={() => handleColorSelect(preset.value)}
                title={preset.name}
                aria-label={`色: ${preset.name}`}
              />
            );
          })}
          {/* 自由選択ピッカー */}
          <div
            className={`custom-color-btn ${!isPresetSelected && settings.tool === 'pen' ? 'active' : ''}`}
            title="自由な色を選ぶ"
          >
            <input
              type="color"
              className="custom-color-input"
              value={settings.color}
              onChange={handleCustomColorChange}
              aria-label="カスタムカラー選択"
            />
          </div>
        </div>
      </section>

      {/* 線の太さ */}
      <section className="tool-section">
        <h2 className="section-title">
          {settings.tool === 'eraser' ? '消しゴムの太さ' : '線の太さ'}
        </h2>
        <div className="size-control-group">
          <div className="size-preview-dot" aria-hidden="true">
            <span
              style={{
                display: 'inline-block',
                width: `${Math.min(settings.size, 30)}px`,
                height: `${Math.min(settings.size, 30)}px`,
                borderRadius: '50%',
                backgroundColor: settings.tool === 'eraser' ? '#64748b' : settings.color,
                transition: 'width 0.1s ease, height 0.1s ease',
              }}
            />
          </div>
          <input
            type="range"
            min="1"
            max="50"
            value={settings.size}
            onChange={handleSizeChange}
            className="size-slider"
            aria-label="太さスライダー"
          />
          <span className="size-value">{settings.size}px</span>
        </div>
      </section>

      {/* 操作アクション */}
      <section className="tool-section">
        <h2 className="section-title">操作</h2>
        <div className="action-btn-group">
          <button
            type="button"
            className="tool-btn"
            onClick={onUndo}
            disabled={!canUndo}
            title="1手戻す"
          >
            <Undo2 size={18} />
            <span>戻す</span>
          </button>
          <button
            type="button"
            className="tool-btn tool-btn-danger"
            onClick={onClear}
            title="キャンバスを全消去"
          >
            <Trash2 size={18} />
            <span>全消去</span>
          </button>
        </div>
      </section>

      {/* 保存アクション */}
      <section className="tool-section">
        <button
          type="button"
          className="tool-btn tool-btn-primary"
          onClick={onDownload}
          title="描いた絵を保存する"
        >
          <Download size={18} />
          <span>画像保存</span>
        </button>
      </section>
    </aside>
  );
}

import { useRef, useEffect, useState, useCallback, PointerEvent } from 'react';
import { CanvasBoardProps } from '../types';

const MAX_HISTORY = 20;

export default function CanvasBoard({
  settings,
  onHistoryChange,
  clearTrigger,
  undoTrigger,
  downloadTrigger,
}: CanvasBoardProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isDrawingRef = useRef<boolean>(false);
  const lastPosRef = useRef<{ x: number; y: number } | null>(null);
  const historyRef = useRef<ImageData[]>([]);

  const [, setCanvasReady] = useState(false);

  // キャンバスを白で初期化
  const fillCanvasBackground = useCallback((ctx: CanvasRenderingContext2D, width: number, height: number) => {
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);
  }, []);

  // 履歴の保存
  const pushHistory = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    historyRef.current.push(imageData);

    if (historyRef.current.length > MAX_HISTORY) {
      historyRef.current.shift();
    }
    // 戻せる履歴（現在の一歩手前が存在するか）
    onHistoryChange?.(historyRef.current.length > 1);
  }, [onHistoryChange]);

  // 初期サイズ設定とリサイズ処理
  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let prevData: ImageData | null = null;

    const resizeCanvas = () => {
      const rect = container.getBoundingClientRect();
      const newWidth = Math.floor(rect.width);
      const newHeight = Math.floor(rect.height);

      if (canvas.width === newWidth && canvas.height === newHeight) return;

      if (canvas.width > 0 && canvas.height > 0) {
        try {
          prevData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        } catch {
          prevData = null;
        }
      }

      canvas.width = newWidth;
      canvas.height = newHeight;

      fillCanvasBackground(ctx, newWidth, newHeight);

      if (prevData) {
        ctx.putImageData(prevData, 0, 0);
      }

      // 初回なら初期スナップショットを履歴に入れる
      if (historyRef.current.length === 0) {
        const initialSnapshot = ctx.getImageData(0, 0, canvas.width, canvas.height);
        historyRef.current = [initialSnapshot];
        onHistoryChange?.(false);
      }

      setCanvasReady(true);
    };

    resizeCanvas();

    const resizeObserver = new ResizeObserver(() => {
      resizeCanvas();
    });
    resizeObserver.observe(container);

    return () => {
      resizeObserver.disconnect();
    };
  }, [fillCanvasBackground, onHistoryChange]);

  // 全消去トリガーの監視
  useEffect(() => {
    if (clearTrigger === 0) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    fillCanvasBackground(ctx, canvas.width, canvas.height);
    pushHistory();
  }, [clearTrigger, fillCanvasBackground, pushHistory]);

  // アンドゥトリガーの監視
  useEffect(() => {
    if (undoTrigger === 0) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (historyRef.current.length > 1) {
      historyRef.current.pop(); // 現在の状態を捨てる
      const previousState = historyRef.current[historyRef.current.length - 1];
      ctx.putImageData(previousState, 0, 0);
      onHistoryChange?.(historyRef.current.length > 1);
    }
  }, [undoTrigger, onHistoryChange]);

  // ダウンロードトリガーの監視
  useEffect(() => {
    if (downloadTrigger === 0) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    try {
      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      const timestamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
      link.download = `drawing-${timestamp}.png`;
      link.href = dataUrl;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch {
      // エラー時はフォールバック
    }
  }, [downloadTrigger]);

  // 描画座標の取得
  const getCoordinates = (e: PointerEvent<HTMLCanvasElement>): { x: number; y: number } => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    };
  };

  const handlePointerDown = (e: PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // タッチやマウスのポインタキャプチャ設定
    try {
      canvas.setPointerCapture(e.pointerId);
    } catch {
      // 一部ブラウザの安全対策
    }

    isDrawingRef.current = true;
    const coords = getCoordinates(e);
    lastPosRef.current = coords;

    // 点を描画（クリックしただけでも打てるように）
    ctx.beginPath();
    ctx.arc(coords.x, coords.y, settings.size / 2, 0, Math.PI * 2);
    ctx.fillStyle = settings.tool === 'eraser' ? '#ffffff' : settings.color;
    ctx.fill();
  };

  const handlePointerMove = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawingRef.current) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const coords = getCoordinates(e);
    const prev = lastPosRef.current || coords;

    ctx.beginPath();
    ctx.moveTo(prev.x, prev.y);
    ctx.lineTo(coords.x, coords.y);
    ctx.strokeStyle = settings.tool === 'eraser' ? '#ffffff' : settings.color;
    ctx.lineWidth = settings.size;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();

    lastPosRef.current = coords;
  };

  const handlePointerUp = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawingRef.current) return;
    isDrawingRef.current = false;
    lastPosRef.current = null;

    const canvas = canvasRef.current;
    if (canvas) {
      try {
        if (canvas.hasPointerCapture(e.pointerId)) {
          canvas.releasePointerCapture(e.pointerId);
        }
      } catch {
        // 安全対策
      }
    }

    pushHistory();
  };

  const handlePointerCancel = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawingRef.current) return;
    isDrawingRef.current = false;
    lastPosRef.current = null;
    const canvas = canvasRef.current;
    if (canvas) {
      try {
        if (canvas.hasPointerCapture(e.pointerId)) {
          canvas.releasePointerCapture(e.pointerId);
        }
      } catch {
        // 安全対策
      }
    }
    pushHistory();
  };

  return (
    <main className="canvas-area" ref={containerRef}>
      <canvas
        ref={canvasRef}
        className="drawing-canvas"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerCancel}
        onPointerLeave={handlePointerUp}
      />
    </main>
  );
}

import { useState } from 'react';
import Toolbar from './components/Toolbar';
import CanvasBoard from './components/CanvasBoard';
import { DrawingSettings } from './types';

const INITIAL_SETTINGS: DrawingSettings = {
  color: '#1e293b',
  size: 8,
  tool: 'pen',
};

export default function App() {
  const [settings, setSettings] = useState<DrawingSettings>(INITIAL_SETTINGS);
  const [canUndo, setCanUndo] = useState<boolean>(false);
  const [clearTrigger, setClearTrigger] = useState<number>(0);
  const [undoTrigger, setUndoTrigger] = useState<number>(0);
  const [downloadTrigger, setDownloadTrigger] = useState<number>(0);

  const handleSettingsChange = (newSettings: Partial<DrawingSettings>) => {
    setSettings((prev) => ({ ...prev, ...newSettings }));
  };

  const handleClear = () => {
    setClearTrigger((prev) => prev + 1);
  };

  const handleUndo = () => {
    setUndoTrigger((prev) => prev + 1);
  };

  const handleDownload = () => {
    setDownloadTrigger((prev) => prev + 1);
  };

  const handleHistoryChange = (undoAvailable: boolean) => {
    setCanUndo(undoAvailable);
  };

  return (
    <div className="app-container">
      {/* ヘッダーエリア */}
      <header className="app-header">
        <h1 className="app-title">🎨 かんたんお絵かきボード</h1>
        <p className="app-guide">
          マウスや指でなぞって描けます。色や太さを変えて自由に描いてみよう！
        </p>
      </header>

      {/* メインレイアウト（ツールバーと描画エリア） */}
      <div className="main-layout">
        <Toolbar
          settings={settings}
          onSettingsChange={handleSettingsChange}
          onClear={handleClear}
          onUndo={handleUndo}
          onDownload={handleDownload}
          canUndo={canUndo}
        />
        <CanvasBoard
          settings={settings}
          onHistoryChange={handleHistoryChange}
          clearTrigger={clearTrigger}
          undoTrigger={undoTrigger}
          downloadTrigger={downloadTrigger}
        />
      </div>
    </div>
  );
}
